Refactor this to use a dict dispatch instead of if/elif and add type hints:

def op(a, b, kind):
    if kind == 'add':
        return a + b
    elif kind == 'sub':
        return a - b
    elif kind == 'mul':
        return a * b
    elif kind == 'div':
        return a / b
    else:
        raise ValueError(kind)
